1	// Re-export everything from the shared adapter-utils/server-utils package.
2	// This file is kept as a convenience shim so existing in-tree
3	// imports (process/, http/, heartbeat.ts) don't need rewriting.
4	import type { ChildProcess } from "node:child_process";
5	import { logger } from "../middleware/logger.js";
6	import * as serverUtils from "@paperclipai/adapter-utils/server-utils";
7	export type { RunProcessResult } from "@paperclipai/adapter-utils/server-utils";
8	
9	type BuildInvocationEnvForLogsOptions = {
10	  runtimeEnv?: NodeJS.ProcessEnv | Record<string, string>;
11	  includeRuntimeKeys?: string[];
12	  resolvedCommand?: string | null;
13	  resolvedCommandEnvKey?: string;
14	};
15	
16	export const runningProcesses: Map<string, { child: ChildProcess; graceSec: number; processGroupId: number | null }> =
17	  serverUtils.runningProcesses;
18	export const MAX_CAPTURE_BYTES = serverUtils.MAX_CAPTURE_BYTES;
19	export const MAX_EXCERPT_BYTES = serverUtils.MAX_EXCERPT_BYTES;
20	export const parseObject = serverUtils.parseObject;
21	export const asString = serverUtils.asString;
22	export const asNumber = serverUtils.asNumber;
23	export const asBoolean = serverUtils.asBoolean;
24	export const asStringArray = serverUtils.asStringArray;
25	export const parseJson = serverUtils.parseJson;
26	export const appendWithCap = serverUtils.appendWithCap;
27	export const appendWithByteCap = serverUtils.appendWithByteCap;
28	export const resolvePathValue = serverUtils.resolvePathValue;
29	export const renderTemplate = serverUtils.renderTemplate;
30	export const redactEnvForLogs = serverUtils.redactEnvForLogs;
31	export const buildPaperclipEnv = serverUtils.buildPaperclipEnv;
32	export const defaultPathForPlatform = serverUtils.defaultPathForPlatform;
33	export const ensurePathInEnv = serverUtils.ensurePathInEnv;
34	export const ensureAbsoluteDirectory = serverUtils.ensureAbsoluteDirectory;
35	export const ensureCommandResolvable = serverUtils.ensureCommandResolvable;
36	export const resolveCommandForLogs = serverUtils.resolveCommandForLogs;
37	
38	export function buildInvocationEnvForLogs(
39	  env: Record<string, string>,
40	  options: BuildInvocationEnvForLogsOptions = {},
41	): Record<string, string> {
42	  const maybeBuildInvocationEnvForLogs = (
43	    serverUtils as typeof serverUtils & {
44	      buildInvocationEnvForLogs?: (
45	        env: Record<string, string>,
46	        options?: BuildInvocationEnvForLogsOptions,
47	      ) => Record<string, string>;
48	    }
49	  ).buildInvocationEnvForLogs;
50	
51	  if (typeof maybeBuildInvocationEnvForLogs === "function") {
52	    return maybeBuildInvocationEnvForLogs(env, options);
53	  }
54	
55	  const merged: Record<string, string> = { ...env };
56	  const runtimeEnv = options.runtimeEnv ?? {};
57	
58	  for (const key of options.includeRuntimeKeys ?? []) {
59	    if (key in merged) continue;
60	    const value = runtimeEnv[key];
61	    if (typeof value !== "string" || value.length === 0) continue;
62	    merged[key] = value;
63	  }
64	
65	  const resolvedCommand = options.resolvedCommand?.trim();
66	  if (resolvedCommand) {
67	    merged[options.resolvedCommandEnvKey ?? "PAPERCLIP_RESOLVED_COMMAND"] = resolvedCommand;
68	  }
69	
70	  return redactEnvForLogs(merged);
71	}
72	
73	// Re-export runChildProcess with the server's pino logger wired in.
74	import type { RunProcessResult } from "@paperclipai/adapter-utils/server-utils";
75	const _runChildProcess = serverUtils.runChildProcess;
76	
77	export async function runChildProcess(
78	  runId: string,
79	  command: string,
80	  args: string[],
81	  opts: {
82	    cwd: string;
83	    env: Record<string, string>;
84	    timeoutSec: number;
85	    graceSec: number;
86	    onLog: (stream: "stdout" | "stderr", chunk: string) => Promise<void>;
87	  },
88	): Promise<RunProcessResult> {
89	  return _runChildProcess(runId, command, args, {
90	    ...opts,
91	    onLogError: (err, id, msg) => logger.warn({ err, runId: id }, msg),
92	  });
93	}
